'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dptts2 = require( './../lib/ndarray.js' );


// FIXTURES //

var COL_MAJOR_NRHS_EQ_ONE = require( './fixtures/col_major_nrhs_eq_one.json' );
var COL_MAJOR_NRHS_GT_ONE = require( './fixtures/col_major_nrhs_gt_one.json' );
var COL_MAJOR_N_EQ_ONE = require( './fixtures/col_major_n_eq_one.json' );
var ROW_MAJOR_NRHS_EQ_ONE = require( './fixtures/row_major_nrhs_eq_one.json' );
var ROW_MAJOR_NRHS_GT_ONE = require( './fixtures/row_major_nrhs_gt_one.json' );
var ROW_MAJOR_N_EQ_ONE = require( './fixtures/row_major_n_eq_one.json' );
var POS_STRIDE_COL_MAJOR_NRHS_EQ_ONE = require( './fixtures/positive-strides/pos_stride_col_major_nrhs_eq_one.json' );
var POS_STRIDE_COL_MAJOR_NRHS_GT_ONE = require( './fixtures/positive-strides/pos_stride_col_major_nrhs_gt_one.json' );
var POS_STRIDE_COL_MAJOR_N_EQ_ONE = require( './fixtures/positive-strides/pos_stride_col_major_n_eq_one.json' );
var POS_STRIDE_ROW_MAJOR_NRHS_EQ_ONE = require( './fixtures/positive-strides/pos_stride_row_major_nrhs_eq_one.json' );
var POS_STRIDE_ROW_MAJOR_NRHS_GT_ONE = require( './fixtures/positive-strides/pos_stride_row_major_nrhs_gt_one.json' );
var POS_STRIDE_ROW_MAJOR_N_EQ_ONE = require( './fixtures/positive-strides/pos_stride_row_major_n_eq_one.json' );
var NEG_STRIDE_COL_MAJOR_NRHS_EQ_ONE = require( './fixtures/negative-strides/neg_stride_col_major_nrhs_eq_one.json' );
var NEG_STRIDE_COL_MAJOR_NRHS_GT_ONE = require( './fixtures/negative-strides/neg_stride_col_major_nrhs_gt_one.json' );
var NEG_STRIDE_COL_MAJOR_N_EQ_ONE = require( './fixtures/negative-strides/neg_stride_col_major_n_eq_one.json' );
var NEG_STRIDE_ROW_MAJOR_NRHS_EQ_ONE = require( './fixtures/negative-strides/neg_stride_row_major_nrhs_eq_one.json' );
var NEG_STRIDE_ROW_MAJOR_NRHS_GT_ONE = require( './fixtures/negative-strides/neg_stride_row_major_nrhs_gt_one.json' );
var NEG_STRIDE_ROW_MAJOR_N_EQ_ONE = require( './fixtures/negative-strides/neg_stride_row_major_n_eq_one.json' );
var OFFSET_COL_MAJOR_NRHS_EQ_ONE = require( './fixtures/offsets/offset_col_major_nrhs_eq_one.json' );
var OFFSET_COL_MAJOR_NRHS_GT_ONE = require( './fixtures/offsets/offset_col_major_nrhs_gt_one.json' );
var OFFSET_COL_MAJOR_N_EQ_ONE = require( './fixtures/offsets/offset_col_major_n_eq_one.json' );
var OFFSET_ROW_MAJOR_NRHS_EQ_ONE = require( './fixtures/offsets/offset_row_major_nrhs_eq_one.json' );
var OFFSET_ROW_MAJOR_NRHS_GT_ONE = require( './fixtures/offsets/offset_row_major_nrhs_gt_one.json' );
var OFFSET_ROW_MAJOR_N_EQ_ONE = require( './fixtures/offsets/offset_row_major_n_eq_one.json' );
var COMPLEX_ACCESS_COL_MAJOR_NRHS_EQ_ONE = require( './fixtures/complex-access/complex_access_col_major_nrhs_eq_one.json' );
var COMPLEX_ACCESS_COL_MAJOR_NRHS_GT_ONE = require( './fixtures/complex-access/complex_access_col_major_nrhs_gt_one.json' );
var COMPLEX_ACCESS_COL_MAJOR_N_EQ_ONE = require( './fixtures/complex-access/complex_access_col_major_n_eq_one.json' );
var COMPLEX_ACCESS_ROW_MAJOR_NRHS_EQ_ONE = require( './fixtures/complex-access/complex_access_row_major_nrhs_eq_one.json' );
var COMPLEX_ACCESS_ROW_MAJOR_NRHS_GT_ONE = require( './fixtures/complex-access/complex_access_row_major_nrhs_gt_one.json' );
var COMPLEX_ACCESS_ROW_MAJOR_N_EQ_ONE = require( './fixtures/complex-access/complex_access_row_major_n_eq_one.json' );


// FUNCTIONS //

/**
* Runs a fixture through the ndarray interface and asserts the result matches the expected solution.
*
* @private
* @param {Object} t - test object
* @param {Object} data - fixture data
* @param {string} msg - assertion message
*/
function runFixture( t, data, msg ) {
	var expected;
	var out;
	var D;
	var E;
	var B;

	D = new Float64Array( data.D );
	E = new Float64Array( data.E );
	B = new Float64Array( data.B );
	expected = new Float64Array( data.expected );

	out = dptts2( data.N, data.nrhs, D, data.sd, data.od, E, data.se, data.oe, B, data.sb1, data.sb2, data.ob ); // eslint-disable-line max-len
	t.strictEqual( out, B, msg + ': returns a reference to `B`' );
	t.deepEqual( out, expected, msg + ': returns expected value' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dptts2, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 12', function test( t ) {
	t.strictEqual( dptts2.length, 12, 'returns expected value' );
	t.end();
});

tape( 'the function returns the input array unchanged if `N` is zero', function test( t ) {
	var expected;
	var out;
	var B;

	B = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	expected = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );

	out = dptts2( 0, 2, new Float64Array( [] ), 1, 0, new Float64Array( [] ), 1, 0, B, 1, 2, 0 ); // eslint-disable-line max-len
	t.strictEqual( out, B, 'returns a reference to `B`' );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function solves `A * X = B` (column-major)', function test( t ) {
	runFixture( t, COL_MAJOR_NRHS_EQ_ONE, 'col-major, nrhs = 1' );
	runFixture( t, COL_MAJOR_NRHS_GT_ONE, 'col-major, nrhs > 1' );
	runFixture( t, COL_MAJOR_N_EQ_ONE, 'col-major, N = 1' );
	t.end();
});

tape( 'the function solves `A * X = B` (row-major)', function test( t ) {
	runFixture( t, ROW_MAJOR_NRHS_EQ_ONE, 'row-major, nrhs = 1' );
	runFixture( t, ROW_MAJOR_NRHS_GT_ONE, 'row-major, nrhs > 1' );
	runFixture( t, ROW_MAJOR_N_EQ_ONE, 'row-major, N = 1' );
	t.end();
});

tape( 'the function supports specifying positive strides', function test( t ) {
	runFixture( t, POS_STRIDE_COL_MAJOR_NRHS_EQ_ONE, 'pos-stride, col-major, nrhs = 1' );
	runFixture( t, POS_STRIDE_COL_MAJOR_NRHS_GT_ONE, 'pos-stride, col-major, nrhs > 1' );
	runFixture( t, POS_STRIDE_COL_MAJOR_N_EQ_ONE, 'pos-stride, col-major, N = 1' );
	runFixture( t, POS_STRIDE_ROW_MAJOR_NRHS_EQ_ONE, 'pos-stride, row-major, nrhs = 1' );
	runFixture( t, POS_STRIDE_ROW_MAJOR_NRHS_GT_ONE, 'pos-stride, row-major, nrhs > 1' );
	runFixture( t, POS_STRIDE_ROW_MAJOR_N_EQ_ONE, 'pos-stride, row-major, N = 1' );
	t.end();
});

tape( 'the function supports specifying negative strides', function test( t ) {
	runFixture( t, NEG_STRIDE_COL_MAJOR_NRHS_EQ_ONE, 'neg-stride, col-major, nrhs = 1' );
	runFixture( t, NEG_STRIDE_COL_MAJOR_NRHS_GT_ONE, 'neg-stride, col-major, nrhs > 1' );
	runFixture( t, NEG_STRIDE_COL_MAJOR_N_EQ_ONE, 'neg-stride, col-major, N = 1' );
	runFixture( t, NEG_STRIDE_ROW_MAJOR_NRHS_EQ_ONE, 'neg-stride, row-major, nrhs = 1' );
	runFixture( t, NEG_STRIDE_ROW_MAJOR_NRHS_GT_ONE, 'neg-stride, row-major, nrhs > 1' );
	runFixture( t, NEG_STRIDE_ROW_MAJOR_N_EQ_ONE, 'neg-stride, row-major, N = 1' );
	t.end();
});

tape( 'the function supports specifying offsets', function test( t ) {
	runFixture( t, OFFSET_COL_MAJOR_NRHS_EQ_ONE, 'offset, col-major, nrhs = 1' );
	runFixture( t, OFFSET_COL_MAJOR_NRHS_GT_ONE, 'offset, col-major, nrhs > 1' );
	runFixture( t, OFFSET_COL_MAJOR_N_EQ_ONE, 'offset, col-major, N = 1' );
	runFixture( t, OFFSET_ROW_MAJOR_NRHS_EQ_ONE, 'offset, row-major, nrhs = 1' );
	runFixture( t, OFFSET_ROW_MAJOR_NRHS_GT_ONE, 'offset, row-major, nrhs > 1' );
	runFixture( t, OFFSET_ROW_MAJOR_N_EQ_ONE, 'offset, row-major, N = 1' );
	t.end();
});

tape( 'the function supports complex access patterns (mixed sign strides and offsets)', function test( t ) {
	runFixture( t, COMPLEX_ACCESS_COL_MAJOR_NRHS_EQ_ONE, 'complex, col-major, nrhs = 1' );
	runFixture( t, COMPLEX_ACCESS_COL_MAJOR_NRHS_GT_ONE, 'complex, col-major, nrhs > 1' );
	runFixture( t, COMPLEX_ACCESS_COL_MAJOR_N_EQ_ONE, 'complex, col-major, N = 1' );
	runFixture( t, COMPLEX_ACCESS_ROW_MAJOR_NRHS_EQ_ONE, 'complex, row-major, nrhs = 1' );
	runFixture( t, COMPLEX_ACCESS_ROW_MAJOR_NRHS_GT_ONE, 'complex, row-major, nrhs > 1' );
	runFixture( t, COMPLEX_ACCESS_ROW_MAJOR_N_EQ_ONE, 'complex, row-major, N = 1' );
	t.end();
});
